- (NSArray *)books {NSArray *b=self.snapshot[@"Books"];return [b isKindOfClass:NSArray.class]?b:@[];}
- (NSDictionary *)selectedBook {NSInteger row=self.shelfTable.clickedRow>=0?self.shelfTable.clickedRow:self.shelfTable.selectedRow;if(row<0||row>=self.filteredBooks.count)return nil;return self.filteredBooks[row];}
- (void)continueBook:(id)sender {NSDictionary *b=[self selectedBook];if(!b){self.message.stringValue=@"请先选择一本书";return;}Emit(@"continue",@{@"BookID":b[@"ID"]});[self.manager orderOut:nil];[self.previousApp activateWithOptions:NSApplicationActivateIgnoringOtherApps];}
- (void)chapterBook:(id)sender {NSDictionary *b=[self selectedBook];if(b)Emit(@"chapters",@{@"BookID":b[@"ID"]});else self.message.stringValue=@"请先选择一本书";}
- (void)bookAction:(id)sender {NSString *kind=[sender representedObject];if([kind isEqual:@"chapters"]){[self chapterBook:sender];return;}if([kind isEqual:@"continue"]){[self continueBook:sender];return;}NSDictionary *b=[self selectedBook];if(b)Emit(@"remove",@{@"BookID":b[@"ID"]});}
