- (void)controlTextDidChange:(NSNotification *)note {if(note.object==self.bookSearch)[self refreshManager];if(note.object==self.chapterSearch)[self filterChapters];}
- (void)controlTextDidEndEditing:(NSNotification *)note {NSTextField *f=note.object;if(f.identifier&&self.fields[f.identifier]==f)[self saveSettings:f];}
- (void)saveSettings:(id)sender {if(self.applying||!self.snapshot)return;NSMutableDictionary *s=[self.snapshot[@"Settings"] mutableCopy],*frame=[s[@"Frame"] mutableCopy];NSCharacterSet *hex=[[NSCharacterSet characterSetWithCharactersInString:@"0123456789abcdefABCDEF"] invertedSet];for(NSString *key in @[@"BackgroundColor",@"TextColor"]){NSString *v=[[(NSTextField *)self.fields[key] stringValue] stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];if(v.length!=7||![v hasPrefix:@"#"]||[[v substringFromIndex:1] rangeOfCharacterFromSet:hex].location!=NSNotFound){self.message.stringValue=@"颜色请输入 # 加 6 位十六进制字符，例如 #000000";self.message.textColor=NSColor.systemRedColor;return;}s[key]=v;}
 for(NSString *key in @[@"Width",@"Height",@"X",@"Y",@"BackgroundTransparency",@"FontSize",@"TextTransparency",@"LineSpacing",@"CollapseDelayMS",@"MenuWidth",@"MenuFontSize"]){NSString *v=[(NSTextField *)self.fields[key] stringValue];NSScanner *scan=[NSScanner scannerWithString:v];double value;if(![scan scanDouble:&value]||!scan.isAtEnd){self.message.stringValue=@"数值格式无效，请输入数字";self.message.textColor=NSColor.systemRedColor;return;}if([@[@"Width",@"Height",@"X",@"Y"] containsObject:key])frame[key]=@(value);else s[key]=@(value);}
 s[@"Frame"]=frame;s[@"Mode"]=[(NSPopUpButton *)self.fields[@"Mode"] indexOfSelectedItem]==1?@"float":@"menu";s[@"AutoCollapse"]=@([(NSButton *)self.fields[@"AutoCollapse"] state]==NSControlStateValueOn);NSMutableDictionary *bindings=[NSMutableDictionary new];NSArray *keys=@[@123,@124,@126,@125,@4,@46,@38,@40,@37,@45,@35,@49],*mods=@[@6144,@2304,@4608,@768];for(NSString *kind in s[@"Hotkeys"]){bindings[kind]=@{@"KeyCode":keys[[(NSPopUpButton *)self.fields[[kind stringByAppendingString:@"Key"]] indexOfSelectedItem]],@"Modifiers":mods[[(NSPopUpButton *)self.fields[[kind stringByAppendingString:@"Mods"]] indexOfSelectedItem]]};}s[@"Hotkeys"]=bindings;Emit(@"saveSettings",@{@"Settings":s});
}
