e]){[self.chapterTable selectRowIndexes:[NSIndexSet indexSetWithIndex:i] byExtendingSelection:NO];[self.chapterTable scrollRowToVisible:i];break;}}}
- (void)filterChapters {NSString *q=self.chapterSearch.stringValue?:@"";self.filteredChapters=[self.chapters filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *c,NSDictionary *bindings){return q.length==0||[c[@"Title"] localizedCaseInsensitiveContainsString:q]||[[c[@"Number"] description] containsString:q];}]];[self.chapterTable reloadData];}
